function learningPage(){return `${header()}<main class="container learning-page"><div class="eyebrow">YOUR PERSONAL LEARNING PATH</div><h1 class="learning-title">Python: Basic to Advanced</h1><p class="learning-intro">Learn Python in simple English through structured lessons, detailed explanations, copyable code examples, expected outputs, common mistakes, and practice tasks.</p><div class="learning-summary"><div><strong>${pythonLessons.length}</strong><span>structured lessons</span></div><div><strong>4</strong><span>learning stages</span></div><div><strong>100%</strong><span>free to study</span></div></div><div class="learning-stage"><div class="stage-heading"><div><div class="eyebrow">STAGE 1</div><h2>Python Foundations</h2></div><span>Beginner</span></div><div class="lesson-grid">${pythonLessons.slice(0,12).map(lessonCard).join('')}</div></div><div class="learning-stage"><div class="stage-heading"><div><div class="eyebrow">STAGE 2</div><h2>Intermediate Python</h2></div><span>Intermediate</span></div><div class="lesson-grid">${pythonLessons.slice(12,20).map(lessonCard).join('')}</div></div><div class="learning-stage"><div class="stage-heading"><div><div class="eyebrow">STAGE 3</div><h2>Advanced Python</h2></div><span>Advanced</span></div><div class="lesson-grid">${pythonLessons.slice(20).map(lessonCard).join('')}</div></div></main>`}
