function lessonPage(){let lesson=pythonLessons[state.selectedLesson]||pythonLessons[0];let prev=state.selectedLesson-1,next=state.selectedLesson+1;return `${header()}<main class="lesson-reader"><div class="reader-top"><button class="back-link" onclick="go('learning')">← Back to My Learning</button><span>Python · Lesson ${state.selectedLesson+1} of ${pythonLessons.length}</span></div><div class="reader-grid"><aside class="reader-sidebar"><div class="eyebrow">PYTHON PATH</div><h3>Basic to Advanced</h3><div class="reader-progress"><span style="width:${((state.selectedLesson+1)/pythonLessons.length)*100}%"></span></div><div class="reader-lesson-list">${pythonLessons.map((x,i)=>`<button class="reader-lesson ${i===state.selectedLesson?'active':''}" onclick="openPythonLesson(${i})"><span>${String(i+1).padStart(2,'0')}</span>${x.title}</button>`).join('')}</div></aside><article class="lesson-article"><div class="eyebrow">${lesson.level} LESSON</div><h1>${lesson.title}</h1><p class="lesson-lead">${lesson.intro}</p>${lesson.sections.map((section,i)=>section[0]==='Code example'?`<section class="content-section"><h2>${section[0]}</h2>${codeBlock(section[1])}</section>`:`<section class="content-section"><h2>${section[0]}</h2><p>${section[1]}</p></section>`).join('')}<section class="content-section"><h2>Expected output</h2><pre class="output-block">${escapeHtml(lesson.output)}</pre></section><section class="practice-box"><div class="eyebrow">PRACTICE TASK</div><h2>Try it yourself</h2><p>${lesson.practice}</p></section><section class="content-section"><h2>Common mistakes to avoid</h2><p>${lesson.mistakes}</p></section><div class="lesson-navigation">${prev>=0?`<button class="secondary" onclick="openPythonLesson(${prev})">← Previous lesson</button>`:'<span></span>'}${next<pythonLessons.length?`<button class="primary" onclick="openPythonLesson(${next})">Next lesson →</button>`:`<button class="primary" onclick="go('learning')">Back to learning path →</button>`}</div></article></div></main>`}
function escapeHtml(value){return String(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function copyCode(event,button){event.stopPropagation();let code=button.closest('.code-example').querySelector('code').innerText;if(!navigator.clipboard){alert('Copy is not available in this browser. Select the code and copy it manually.');return}navigator.clipboard.writeText(code).then(()=>{let old=button.textContent;button.textContent='Copied!';setTimeout(()=>button.textContent=old,1200)}).catch(()=>alert('Copy is not available in this browser. Select the code and copy it manually.'))}
function coursePage(){let c=state.selected||courses[0];let names=['Introduction','Getting started','Core concepts','Practice project','Build something','Next steps'];let total=Math.min(c.lessons,6);let embed=c.playlist?`https://www.youtube.com/embed/videoseries?list=${c.playlist.split('list=')[1]}`:(c.video||'');return `${header()}<div class="course-page"><aside class="side">${brand()}<div class="side-title">Course contents</div>${Array.from({length:total},(_,i)=>`<div class="side-item ${i===0?'active':''}" onclick="selectLesson(${i})"><span>${i+1}. ${names[i]||'Lesson '+(i+1)}</span><span>›</span></div>`).join('')}</aside><main class="mainpanel"><div class="crumb">Courses / ${c.title}</div><div class="lesson-layout"><div class="lesson-list"><h3>${c.title}</h3>${Array.from({length:total},(_,i)=>`<div class="lesson ${i===0?'active':''}" onclick="selectLesson(${i})"><span class="lesson-num">${i+1}</span><span>${names[i]||'Lesson '+(i+1)}</span></div>`).join('')}</div><div class="lesson-content"><div class="video">${embed?`<iframe width="100%" height="100%" src="${embed}" title="${c.title}" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`:`<div class="video-empty">Video link will appear here.</div>`}</div><h1>${c.title}: ${names[0]}</h1><p>${c.desc} This course is connected to the provided learning source.</p><div class="lesson-actions">${c.playlist?`<a class="primary" href="${c.playlist}" target="_blank" rel="noopener">Open full playlist ↗</a>`:''}<button class="secondary" onclick="alert('Add your PDF/notes link in app.js when ready.')">Practice slides ↗</button></div></div></div></main></div>`}
function login(){return `${header()}<div class="login-wrap"><div class="login-card"><div class="eyebrow">WELCOME BACK</div><h1>Sign in to learn.</h1><p style="color:var(--muted);font-size:13px">Continue your coding journey with CodewithHafiz.</p><div class="field"><label>Email</label><input id="email" type="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="password" type="password" placeholder="Your password"></div><button class="primary" style="width:100%" onclick="signin()">Sign in →</button><p style="font-size:12px;color:var(--muted);text-align:center;margin-top:20px">Demo: student@example.com / student123</p></div></div>`}
function dashboard(){return `${header()}<div class="dash-layout"><aside class="dash-side">${brand()}<div class="side-title">Workspace</div><div class="side-item active">▦ Overview</div><div class="side-item">▤ Courses <span>${courses.length}</span></div><div class="side-item">▧ Tutorials <span>4</span></div><div class="side-item">♙ Users</div><div class="side-title">Account</div><div class="side-item">⚙ Account</div></aside><main class="dash-main"><div class="dash-top"><div><div class="eyebrow">YOUR ACADEMY, AT A GLANCE</div><h1>Welcome back, ${state.user||'Hafiz'}.</h1><div style="color:var(--muted);font-size:13px">A little teaching today. A big difference tomorrow.</div></div><button class="new-btn" onclick="alert('Course creator coming next. Add course data in app.js for now.')">＋ New course</button></div><div class="stats"><div class="stat"><small>Total courses</small><strong>${courses.length}</strong><small>published courses</small></div><div class="stat"><small>Tutorials</small><strong>4</strong><small>published</small></div><div class="stat"><small>Registered learners</small><strong>0</strong><small>signed-in student accounts</small></div><div class="stat"><small>Course enrolments</small><strong>0</strong><small>across all courses</small></div></div><div class="dash-banner"><div><div class="eyebrow">MADE FOR THE NEXT GENERATION OF BUILDERS</div><h2>Your knowledge. Their next breakthrough.</h2><div style="color:var(--muted);font-size:12px">Bring your next idea to life with a new course or tutorial.</div></div><button class="primary" onclick="go('courses')">View website →</button></div><div class="table-card"><div class="table-title">Your courses <span style="color:var(--muted);font-size:11px">${courses.length}</span></div><div class="table-row header"><span>Course</span><span>Status</span><span>Lessons</span><span>Category</span></div>${courses.map(c=>`<div class="table-row"><span><b>${c.title}</b></span><span style="color:var(--green)">● Published</span><span>${c.lessons}</span><span>${c.category}</span></div>`).join('')}</div></main></div>`}
function setup(){return `${header()}<main class="container"><div class="eyebrow">START CODING</div><h1 style="font-size:38px">Your coding setup, made simple.</h1><p style="color:var(--muted);max-width:600px">Use these official links to install the tools required for CodewithHafiz lessons.</p><div class="course-grid" style="margin-top:28px"><article class="course"><div class="cover mint"><div class="symbol">Py</div></div><div class="course-body"><h3>Download Python</h3><p>Install Python for Windows from the official Python website.</p><a class="open-course" style="display:block;text-align:center;text-decoration:none" href="https://www.python.org/downloads/" target="_blank">Open Python download ↗</a></div></article><article class="course"><div class="cover blue"><div class="symbol">&lt;/&gt;</div></div><div class="course-body"><h3>Download VS Code</h3><p>Get the official Visual Studio Code editor for your computer.</p><a class="open-course" style="display:block;text-align:center;text-decoration:none" href="https://code.visualstudio.com/download" target="_blank">Open VS Code download ↗</a></div></article><article class="course"><div class="cover pink"><div class="symbol">✦</div></div><div class="course-body"><h3>Python Extension</h3><p>Install Microsoft’s Python extension inside VS Code.</p><a class="open-course" style="display:block;text-align:center;text-decoration:none" href="https://marketplace.visualstudio.com/items?itemName=ms-python.python" target="_blank">Open extension page ↗</a></div></article></div></main>`}
function aiSafe(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function aiRenderText(s){return aiSafe(s).replace(/```([a-zA-Z0-9_+-]*)\n([\s\S]*?)```/g,(m,lang,code)=>`<div class="ai-code"><div><span>${aiSafe(lang||'code')}</span><button onclick="aiCopy(this,${JSON.stringify(code)})">Copy code</button><button onclick="aiInsert(${JSON.stringify(code)})">Insert into editor</button></div><pre>${aiSafe(code)}</pre></div>`).replace(/\n/g,'<br>')}
function aiCopy(btn,code){navigator.clipboard?.writeText(code);const old=btn.textContent;btn.textContent='Copied';setTimeout(()=>btn.textContent=old,1000)}
function aiInsert(code){if(typeof labFiles==='undefined'){alert('Open Code Lab first.');return} if(typeof labCurrent==='undefined')labCurrent='main.py';labFiles[labCurrent]=code;try{localStorage.setItem('cwh_code_lab_files',JSON.stringify(labFiles))}catch(e){};go('lab')}
async function askAI(){const box=document.getElementById('ai-prompt');if(!box||aiBusy)return;const prompt=box.value.trim();if(!prompt)return;aiMessages.push({role:'user',content:prompt});box.value='';aiBusy=true;render();try{const endpoint=window.CODEWITHHAFIZ_AI_ENDPOINT||'/api/ai';const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:aiMessages.slice(-12)})});const data=await res.json();if(!res.ok)throw new Error(data.error||'AI request failed');aiMessages.push({role:'assistant',content:data.output||data.text||'No response returned.'})}catch(e){aiMessages.push({role:'assistant',content:'AI connection error: '+e.message+'\n\nConnect the secure /api/ai backend and add your API key there. Never put the API key in site.js.'})}finally{aiBusy=false;render()}}
function clearAI(){aiMessages=[];render()}
function aiChatPage(){return `${header()}<main class="ai-page"><div class="ai-heading"><div><div class="eyebrow">CODEWITHHAFIZ AI</div><h1>AI Code Assistant</h1><p>Ask for code, debugging, explanations, refactoring, examples, or complete projects.</p></div><button class="secondary" onclick="clearAI()">Clear chat</button></div><div class="ai-chat">${aiMessages.length?aiMessages.map(m=>`<div class="ai-message ${m.role}"><div class="ai-role">${m.role==='user'?'You':'CodewithHafiz AI'}</div><div>${aiRenderText(m.content)}</div></div>`).join(''):`<div class="ai-empty"><div class="ai-empty-icon">AI</div><h2>What do you want to build?</h2><p>Try: “Write a Python calculator with functions and explain every part.”</p></div>`}${aiBusy?'<div class="ai-message assistant"><div class="ai-role">CodewithHafiz AI</div><div>Thinking…</div></div>':''}</div><div class="ai-compose"><textarea id="ai-prompt" placeholder="Ask AI to write or fix any code…" onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();askAI()}"></textarea><button class="primary" onclick="askAI()" ${aiBusy?'disabled':''}>${aiBusy?'Working…':'Ask AI →'}</button></div><div class="ai-note">Your API key stays on the secure backend. Do not paste an API key into this website.</div></main>`}
const LAB_DEFAULT_FILES={
  'main.py':`# Welcome to CodewithHafiz Code Lab\nname = "Hafiz"\nprint(f"Hello, {name}!")\n\nfor i in range(1, 4):\n    print("Learning Python", i)`,
  'index.html':`<!doctype html>\n<html>\n<head><meta charset="UTF-8"><title>My Page</title></head>\n<body>\n  <h1>Hello CodewithHafiz!</h1>\n  <p>Edit this file and click Run.</p>\n</body>\n</html>`,
  'style.css':`body {\n  font-family: Arial, sans-serif;\n  padding: 30px;\n}`,
  'script.js':`console.log("Hello from JavaScript!");\ndocument.body.insertAdjacentHTML("beforeend", "<p>JavaScript is running.</p>");`
};
let labFiles={};
let labCurrent='main.py';
let labOutput='';
let labReady=false;
function labLoad(){
  try{const saved=JSON.parse(localStorage.getItem('cwh_code_lab_files')||'null');labFiles=saved&&typeof saved==='object'?saved:{...LAB_DEFAULT_FILES};}
  catch(e){labFiles={...LAB_DEFAULT_FILES};}
  if(!labFiles[labCurrent])labCurrent=Object.keys(labFiles)[0]||'main.py';
}
function labSave(){try{localStorage.setItem('cwh_code_lab_files',JSON.stringify(labFiles))}catch(e){}}
function labExt(name){return (name.split('.').pop()||'').toLowerCase()}
function labIcon(name){const e=labExt(name);const map={py:['PY','py'],js:['JS','js'],ts:['TS','ts'],html:['HTML','html'],htm:['HTML','html'],css:['#','css'],json:['{}','json'],java:['☕','java'],cpp:['C++','cpp'],c:['C','c'],cs:['C#','cs'],php:['PHP','php'],rb:['RB','rb'],go:['GO','go'],rs:['RS','rs'],md:['M','md'],sql:['DB','sql'],jsx:['JSX','jsx'],tsx:['TSX','tsx'],xml:['XML','xml'],sh:['SH','sh']};const x=map[e]||['·','plain'];return `<span class="lab-file-icon icon-${x[1]}">${x[0]}</span>`}
function labLanguage(name){const e=labExt(name);return {py:'Python',js:'JavaScript',ts:'TypeScript',html:'HTML',htm:'HTML',css:'CSS',json:'JSON',java:'Java',cpp:'C++',c:'C',cs:'C#',php:'PHP',rb:'Ruby',go:'Go',rs:'Rust',md:'Markdown',sql:'SQL',jsx:'JSX',tsx:'TSX',xml:'XML',sh:'Shell'}[e]||'Plain Text'}
function labEscape(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function labHighlight(code,name){
  const e=labExt(name); const tokens=[];
  let s=labEscape(code);
  const protect=(regex,cls)=>{s=s.replace(regex,m=>{const id=tokens.length;tokens.push(`<span class="${cls}">${m}</span>`);return `@@LABTOKEN${id}@@`})};
  protect(/(\/\/[^\n]*|#[^\n]*|\/\*[\s\S]*?\*\/)/g,'tok-comment');
  protect(/(&quot;(?:[^&]|&(?!quot;))*?&quot;|&#39;(?:[^&]|&(?!#39;))*?&#39;|`[^`]*`)/g,'tok-string');
  s=s.replace(/\b(\d+(?:\.\d+)?)\b/g,'<span class="tok-number">$1</span>');
  let keywords='';
  if(e==='py')keywords='and|as|assert|break|class|continue|def|elif|else|False|finally|for|from|if|import|in|is|None|not|or|pass|print|raise|return|True|try|while|with|yield|lambda|range|len|input|int|float|str|list|dict|set|tuple';
  else if(['js','ts','jsx','tsx'].includes(e))keywords='const|let|var|function|return|if|else|for|while|class|new|import|from|export|async|await|true|false|null|undefined|console|document|this|throw|try|catch';
  else if(['java','c','cpp','cs'].includes(e))keywords='int|float|double|char|void|return|if|else|for|while|class|public|private|static|new|true|false|null|using|include|namespace|String|boolean|auto|const';
  else keywords='true|false|null|SELECT|FROM|WHERE|INSERT|UPDATE|DELETE|CREATE|TABLE|AND|OR|NOT';
  if(keywords)s=s.replace(new RegExp('\\b('+keywords+')\\b','g'),'<span class="tok-keyword">$1</span>');
  s=s.replace(/\b([A-Za-z_$][\w$]*)(?=\s*\()/g,'<span class="tok-function">$1</span>');
  s=s.replace(/@@LABTOKEN(\d+)@@/g,(_,i)=>tokens[Number(i)]);
  return s;
}
function labLineNumbers(code){return Array.from({length:Math.max(1,code.split('\n').length)},(_,i)=>i+1).join('\n')}
function labRenderFiles(){return Object.keys(labFiles).map(name=>`<button class="lab-file ${name===labCurrent?'active':''}" onclick="labOpenFile(${JSON.stringify(name)})">${labIcon(name)}<span>${labEscape(name)}</span></button>`).join('')}
function labOpenFile(name){if(!(name in labFiles))return;labCurrent=name;labSave();labUpdateEditor();}
function labUpdateEditor(){const ta=document.getElementById('lab-editor');const pre=document.getElementById('lab-highlight');const gutter=document.getElementById('lab-gutter');if(!ta||!pre||!gutter)return;ta.value=labFiles[labCurrent]||'';pre.innerHTML=labHighlight(ta.value,labCurrent)+'\n';gutter.textContent=labLineNumbers(ta.value);const lang=document.getElementById('lab-language');if(lang)lang.textContent=labLanguage(labCurrent);const list=document.getElementById('lab-file-list');if(list)list.innerHTML=labRenderFiles();}
function labEditorInput(){const ta=document.getElementById('lab-editor');if(!ta)return;labFiles[labCurrent]=ta.value;labSave();const pre=document.getElementById('lab-highlight');const gutter=document.getElementById('lab-gutter');pre.innerHTML=labHighlight(ta.value,labCurrent)+'\n';gutter.textContent=labLineNumbers(ta.value);}
function labSyncScroll(){const ta=document.getElementById('lab-editor'),pre=document.getElementById('lab-highlight'),g=document.getElementById('lab-gutter');if(ta){pre.scrollTop=ta.scrollTop;pre.scrollLeft=ta.scrollLeft;g.scrollTop=ta.scrollTop}}
function labNewFile(){const name=prompt('File name (example: app.py, index.html, main.js):','new_file.py');if(!name)return;if(labFiles[name]){alert('That file already exists.');return}labFiles[name]='';labCurrent=name;labSave();render();}
function labNewFolder(){const folder=prompt('Folder name:','src');if(!folder)return;const name=folder.replace(/[\\/]+$/,'')+'/main.py';if(!labFiles[name])labFiles[name]='# '+folder+'\\nprint("Hello from '+folder+'")';labCurrent=name;labSave();render();}
function labDeleteFile(){if(Object.keys(labFiles).length<=1){alert('Keep at least one file in the project.');return}if(!confirm('Delete '+labCurrent+'?'))return;delete labFiles[labCurrent];labCurrent=Object.keys(labFiles)[0];labSave();render();}
function labClearOutput(){labOutput='';const o=document.getElementById('lab-output');if(o)o.textContent='';}
function labWriteOutput(text){labOutput+=String(text)+'\n';const o=document.getElementById('lab-output');if(o){o.textContent=labOutput;o.scrollTop=o.scrollHeight}}
function labRun(){const e=labExt(labCurrent),code=labFiles[labCurrent]||'';labOutput='';const status=document.getElementById('lab-status');if(status)status.textContent='Running…';
  if(['html','htm'].includes(e)){const html=code;const css=labFiles['style.css']||'';const js=labFiles['script.js']||'';const frame=document.getElementById('lab-preview-frame');if(frame){const doc=html.includes('<html')?html:`<!doctype html><html><head><style>${css}</style></head><body>${html}<script>${js.replace(/<\/script>/gi,'<\\/script>')}<\/script></body></html>`;frame.srcdoc=doc;labWriteOutput('HTML preview opened.');} }
  else if(e==='css'){const frame=document.getElementById('lab-preview-frame');if(frame){frame.srcdoc=`<style>${code}</style><div class="lab-preview-sample">CSS preview — edit your HTML/CSS files to build the page.</div>`;labWriteOutput('CSS preview opened.')}}
  else if(['js','jsx'].includes(e)){try{const result=[];const original=console.log;console.log=(...a)=>result.push(a.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' '));try{new Function(code)();}finally{console.log=original;}labWriteOutput(result.join('\n')||'JavaScript finished with no console output.')}catch(err){labWriteOutput('JavaScript Error: '+err.message)}}
  else if(e==='py'){labRunPythonLite(code)}
  else {labWriteOutput(labLanguage(labCurrent)+' runner is not embedded in the browser. You can still edit and download this file.');}
  if(status)status.textContent='Ready';
}
function labRunPythonLite(code){
  const lines=code.replace(/\r/g,'').split('\n');const vars={};let out=[];let i=0;
  const val=x=>{x=x.trim();if(/^(['\"]).*\1$/.test(x))return x.slice(1,-1);if(/^\d+(\.\d+)?$/.test(x))return Number(x);if(x==='True')return true;if(x==='False')return false;if(x==='None')return null;if(/^f["']/.test(x)){let t=x.slice(2,-1);return t.replace(/\{([^}]+)\}/g,(_,k)=>String(val(k)));}if(x in vars)return vars[x];try{return Function('v','return ('+x+')')(vars)}catch{return x}};
  const emit=x=>{if(x.startsWith('print(')&&x.endsWith(')')){const inside=x.slice(6,-1);const parts=inside.split(',').map(v=>val(v));out.push(parts.map(v=>v===null?'None':String(v)).join(' '));}else if(x.startsWith('input(')){out.push('[input() is not available in offline browser mode]')}};
  while(i<lines.length){let raw=lines[i],trim=raw.trim();if(!trim||trim.startsWith('#')){i++;continue}
    let m=trim.match(/^([A-Za-z_]\w*)\s*=\s*(.+)$/);if(m){vars[m[1]]=val(m[2]);i++;continue}
    m=trim.match(/^for\s+([A-Za-z_]\w*)\s+in\s+range\((\d+)(?:\s*,\s*(\d+))?\):$/);if(m){let start=m[2]?Number(m[2]):0,end=m[3]?Number(m[3]):Number(m[2]),j=i+1,body=[];while(j<lines.length&&(lines[j].startsWith(' ')||lines[j].startsWith('\t'))){body.push(lines[j].trim());j++}for(let n=start;n<end;n++){vars[m[1]]=n;body.forEach(b=>emit(b))}i=j;continue}
    if(/^print\(/.test(trim)){emit(trim);i++;continue}
    out.push('[Python Lite] Unsupported statement: '+trim);i++;
  }
  labWriteOutput(out.join('\n')||'Program finished with no output.');
}
function labDownloadOffline(){
  const offline=labOfflineDocument();const blob=new Blob([offline],{type:'text/html;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='CodewithHafiz-Code-Lab-Offline.html';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
function labOfflineDocument(){const files=JSON.stringify(labFiles).replace(/</g,'\\u003c');return `<!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CodewithHafiz Code Lab Offline</title><style>body{margin:0;background:#0b1110;color:#dce9e3;font:14px Arial}header{height:54px;background:#101918;border-bottom:1px solid #24332e;display:flex;align-items:center;padding:0 18px;gap:14px}b{color:#6ee7a8}.app{display:grid;grid-template-columns:240px 1fr;height:calc(100vh - 54px)}aside{background:#0d1513;border-right:1px solid #24332e;padding:14px}.file{display:block;width:100%;background:none;color:#c7d3ce;border:0;text-align:left;padding:9px;border-radius:6px;cursor:pointer}.file.active{background:#173328;color:#fff}.icon{display:inline-block;width:42px;color:#63e6a0;font-size:10px}.main{display:grid;grid-template-rows:1fr 180px;min-width:0}.editor{display:grid;grid-template-columns:45px 1fr;position:relative;min-height:0}.gutter{padding:14px 8px;text-align:right;color:#53635d;background:#0b1110;line-height:1.65;white-space:pre;overflow:hidden}.wrap{position:relative;min-width:0}.highlight,textarea{position:absolute;inset:0;margin:0;padding:14px;font:14px/1.65 Consolas,monospace;white-space:pre;overflow:auto;tab-size:4}.highlight{pointer-events:none}.kw{color:#65d7ff}.str{color:#f5c26b}.num{color:#b9f27c}.com{color:#70827a}textarea{resize:none;background:transparent;color:transparent;caret-color:#fff;border:0;outline:0;z-index:2}.bottom{border-top:1px solid #24332e;background:#0d1513;display:grid;grid-template-columns:1fr 1fr}.panel{padding:12px;overflow:auto}.preview{width:100%;height:100%;border:0;background:white}.actions{margin-left:auto;display:flex;gap:7px}.btn{background:#183b2c;color:#dff9eb;border:1px solid #2c664b;border-radius:6px;padding:7px 11px;cursor:pointer}.run{background:#1b9a5c;color:white;border-color:#35c77d}.out{white-space:pre-wrap;color:#b9c8c1;font:12px/1.6 Consolas,monospace}</style></head><body><header><b>CodewithHafiz</b><span>Code Lab — Offline</span><div class="actions"><button class="btn run" id="run">▶ Run</button><button class="btn" id="save">Download Project</button></div></header><div class="app"><aside><b>EXPLORER</b><div id="files"></div></aside><div class="main"><div class="editor"><div class="gutter" id="gutter"></div><div class="wrap"><pre class="highlight" id="hi"></pre><textarea id="ed" spellcheck="false"></textarea></div></div><div class="bottom"><div class="panel"><b>TERMINAL / OUTPUT</b><div class="out" id="out">Ready.</div></div><div class="panel"><b>PREVIEW</b><iframe class="preview" id="frame" sandbox="allow-scripts"></iframe></div></div></div></div><script>const files=${files};let cur=Object.keys(files)[0]||'main.py';const ed=document.getElementById('ed'),hi=document.getElementById('hi'),gut=document.getElementById('gutter'),list=document.getElementById('files'),out=document.getElementById('out');function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function render(){list.innerHTML=Object.keys(files).map(n=>'<button class="file '+(n===cur?'active':'')+'" data-n="'+n.replace(/"/g,'&quot;')+'"><span class="icon">'+(n.split('.').pop()||'TXT').toUpperCase()+'</span>'+n+'</button>').join('');ed.value=files[cur]||'';hi.innerHTML=esc(ed.value);gut.textContent=Array.from({length:Math.max(1,ed.value.split('\\n').length)},(_,i)=>i+1).join('\\n')}list.onclick=e=>{let b=e.target.closest('[data-n]');if(b){files[cur]=ed.value;cur=b.dataset.n;render()}};ed.oninput=()=>{files[cur]=ed.value;hi.innerHTML=esc(ed.value);gut.textContent=Array.from({length:Math.max(1,ed.value.split('\\n').length)},(_,i)=>i+1).join('\\n')};ed.onscroll=()=>{hi.scrollTop=ed.scrollTop;hi.scrollLeft=ed.scrollLeft;gut.scrollTop=ed.scrollTop};document.getElementById('run').onclick=()=>{files[cur]=ed.value;let e=cur.split('.').pop().toLowerCase(),c=ed.value;out.textContent='';if(['html','htm'].includes(e)){let css=files['style.css']||'',js=files['script.js']||'';document.getElementById('frame').srcdoc=c.includes('<html')?c:'<style>'+css+'</style>'+c+'<script>'+js.replace(/<\\/script>/gi,'<\\\\/script>')+'<\\/script>';out.textContent='HTML preview opened.'}else if(e==='js'){try{let a=[];let old=console.log;console.log=(...x)=>a.push(x.join(' '));new Function(c)();console.log=old;out.textContent=a.join('\\n')||'JavaScript finished.'}catch(x){out.textContent='JavaScript Error: '+x.message}}else if(e==='py'){out.textContent='Offline Python runner: this download includes a lightweight Python practice runner for print(), variables, f-strings and simple range() loops. Full Python packages are not available without an embedded Python runtime.';let lines=c.split('\\n');let vars={};for(let l of lines){let m=l.trim().match(/^([A-Za-z_]\\w*)\\s*=\\s*["\\\'](.*)["\\\']$/);if(m)vars[m[1]]=m[2];let p=l.trim().match(/^print\\((.*)\\)$/);if(p)out.textContent+='\\n'+p[1].replace(/["\\\']/g,'').replace(/\\{(\\w+)\\}/g,(_,k)=>vars[k]||'')}}else out.textContent='No browser runtime is embedded for '+e+'. Edit/download this file instead.'};document.getElementById('save').onclick=()=>{const b=new Blob([JSON.stringify(files,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='CodewithHafiz-project.json';a.click();URL.revokeObjectURL(a.href)};render();</script></body></html>`}
function labInit(){labLoad();labReady=true;labUpdateEditor();}
function codeLabPage(){labLoad();return `${header()}<main class="lab-page lab-vscode"><div class="lab-vscode-titlebar"><div class="lab-vscode-title"><span class="lab-green-dot"></span><b>CodewithHafiz</b><span>Code Lab</span></div><div class="lab-title-actions"><button class="lab-title-btn" onclick="labDownloadOffline()" title="Download an offline Code Lab">⇩ Download Offline</button><button class="lab-title-btn" onclick="go('ai')">✦ AI Assistant</button></div></div><div class="lab-vscode-shell"><aside class="lab-activity"><button class="lab-activity-btn active" title="Explorer">▤</button><button class="lab-activity-btn" onclick="go('ai')" title="AI Assistant">✦</button><button class="lab-activity-btn" title="Search">⌕</button><button class="lab-activity-btn" title="Source Control">⑂</button><button class="lab-activity-btn" title="Run">▷</button><div class="lab-activity-spacer"></div><button class="lab-activity-btn" title="Settings">⚙</button></aside><aside class="lab-explorer"><div class="lab-explorer-head"><span>EXPLORER</span><span class="lab-muted">···</span></div><div class="lab-project"><span>⌄</span> CODEWITHHAFIZ</div><div id="lab-file-list" class="lab-file-list">${labRenderFiles()}</div><div class="lab-explorer-footer"><button onclick="labNewFile()">＋ New File</button><button onclick="labNewFolder()">＋ Folder</button><button onclick="labDeleteFile()">♲ Delete</button></div></aside><section class="lab-center"><div class="lab-tabs"><button class="lab-tab active">${labIcon(labCurrent)}<span>${labEscape(labCurrent)}</span><i>×</i></button><div class="lab-tab-spacer"></div><span class="lab-language" id="lab-language">${labLanguage(labCurrent)}</span><button class="lab-editor-action" onclick="labRun()">▶ Run</button><button class="lab-editor-action" onclick="labClearOutput()">Clear</button></div><div class="lab-editor-wrap"><div class="lab-gutter" id="lab-gutter"></div><div class="lab-code-area"><pre id="lab-highlight" class="lab-highlight"></pre><textarea id="lab-editor" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off" oninput="labEditorInput()" onscroll="labSyncScroll()" onkeydown="if(event.key==='Tab'){event.preventDefault();const s=this.selectionStart;this.value=this.value.slice(0,s)+'    '+this.value.slice(this.selectionEnd);this.selectionStart=this.selectionEnd=s+4;labEditorInput()}"></textarea></div></div><div class="lab-bottom"><div class="lab-bottom-head"><div><button class="lab-panel-tab active">TERMINAL</button><button class="lab-panel-tab">OUTPUT</button><button class="lab-panel-tab">PROBLEMS</button></div><span id="lab-status">Ready</span></div><div class="lab-bottom-content"><pre id="lab-output" class="lab-output">${labEscape(labOutput||'Run your code to see output here.')}</pre><div class="lab-preview-wrap"><div class="lab-preview-head">PREVIEW</div><iframe id="lab-preview-frame" sandbox="allow-scripts" class="lab-preview-frame"></iframe></div></div></div></section><aside class="lab-ai"><div class="lab-ai-head"><span>✦ AI ASSISTANT</span><button onclick="go('ai')">↗</button></div><div class="lab-ai-body"><div class="lab-ai-avatar">✦</div><h3>CodewithHafiz AI</h3><p>Ask me to explain, debug, improve, or generate code for your current project.</p><div class="lab-ai-prompts"><button onclick="go('ai')">Explain this code</button><button onclick="go('ai')">Find bugs</button><button onclick="go('ai')">Improve my code</button></div></div><div class="lab-ai-compose"><input placeholder="Ask AI about your code…" onclick="go('ai')"><button onclick="go('ai')">↑</button></div></aside></div><div class="lab-statusbar"><span>✓ CodewithHafiz Code Lab</span><span id="lab-status-lang">${labLanguage(labCurrent)}</span><span>Spaces: 4</span><span>UTF-8</span><span class="lab-status-green">● Offline-ready</span></div></main><script>setTimeout(labInit,0)</script>`}

function go(p){state.page=p;render()}
function openCourse(id){state.selected=courses.find(c=>c.id===id);state.page='course';render()}
function openPythonLesson(index){state.selectedLesson=index;state.page='lesson';render();window.scrollTo?.(0,0)}
function selectLesson(){alert('This course lesson is connected to its video playlist. The detailed Python learning path is available in My learning.')}
function signin(){let e=$('#email').value,p=$('#password').value;if((e==='student@example.com'&&p==='student123')||(e==='admin@codewithhafiz.com'&&p==='Hafiz@123')){state.user=e.split('@')[0];state.page='courses';render()}else alert('Demo login: student@example.com / student123')}
function logout(){state.user=null;state.page='courses';render()}
function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';document.documentElement.style.setProperty('--bg',state.theme==='dark'?'#111916':'#f7f9f8');document.documentElement.style.setProperty('--surface',state.theme==='dark'?'#19231f':'#fff');document.documentElement.style.setProperty('--text',state.theme==='dark'?'#e7f0eb':'#17211d');render()}
function render(){const app=document.getElementById('app');if(!app)return;let html=state.page==='ai'?aiChatPage():state.page==='lab'?codeLabPage():state.page==='course'?coursePage():state.page==='lesson'?lessonPage():state.page==='learning'?learningPage():state.page==='login'?login():state.page==='dashboard'?dashboard():state.page==='setup'?setup():home();app.innerHTML=html}
